import {GOAT_COST_TYPES,GOAT} from './goat-config.js';import {goatWelfare} from './goat-welfare.js';import {goatPrice} from './goat-market-policy.js';
/** Actual shared-ledger ranch result; mission rewards and shared-tank refill costs are explicitly separate. @param {import('./engine.js').State} state */
export function goatEconomics(state){const g=state.goat,rows=state.ledger,revenue=rows.filter(l=>l.type==='goat_sale').reduce((n,l)=>n+l.amount,0),costs=-rows.filter(l=>GOAT_COST_TYPES.includes(l.type)).reduce((n,l)=>n+l.amount,0),allocated=costs/Math.max(1,3+(g?.stats.bought||0));return {revenue,costs,net:revenue-costs,allocated,sales:g?.sales.map(s=>({...s,allocatedCost:allocated,allocatedNet:s.price-allocated}))||[]};}
/** One bounded sample every six shared game hours, never UI/real time. @param {import('./engine.js').State} state */
export function sampleGoatHistory(state){const g=state.goat,tick=state.tick+1;if(!g?.visited||tick%6!==0)return;const welfare=goatWelfare(g,state.weather);g.history.push({tick,nutrition:g.nutrition,hydration:g.hydration,comfort:welfare.score,growth:g.herd.reduce((n,h)=>n+h.growth,0)/g.herd.length,hayUsedG:g.stats.hayUsedG,waterUsedMl:g.stats.waterUsedMl,browseUsedG:g.stats.browseUsedG,profit:goatEconomics(state).net});if(g.history.length>GOAT.historyMax)g.history.shift();}
/** @param {import('./engine.js').State} state */
export function goatInsight(state){const g=state.goat,welfare=g?goatWelfare(g,state.weather):null;return {welfare,economics:goatEconomics(state),quotes:g?.herd.map(h=>({id:h.id,growth:h.growth,condition:h.condition,base:130,conditionValue:35*h.condition,dayBonus:5*(Math.floor(state.tick/24)%4),price:h.growth===1&&h.condition>=GOAT.readyCondition?goatPrice(h.condition,state.tick):0}))||[],history:g?.history.map(h=>({...h}))||[]};}
